changeSet.sql:
ALTER TABLE hive_agent_policy ENABLE ROW LEVEL SECURITY;
ALTER TABLE hive_agent_policy FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hive_agent_policy
    USING (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1))
    WITH CHECK (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON hive_agent_policy;
ALTER TABLE hive_agent_policy NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hive_agent_policy DISABLE ROW LEVEL SECURITY;

